    adcs_status_t status = ADCS_OK;
    unint32 m = 0U;
    double v[3];
    double r_dipole[3];
    size_t i;

    /* Null checks */
    if ((requested == NULL) || (area_turns == NULL) || (resistance == NULL) || 
        (voltage_limit == NULL) || (voltage == NULL) || (realized == NULL) || (mask == NULL)) {
        voltage->x = 0.0; voltage->y = 0.0; voltage->z = 0.0;
        realized->x = 0.0; realized->y = 0.0; realized->z = 0.0;
        *mask = 0U;
        return ADCS_E_NULL;
    }

    /* Validate inputs per axis before conversion */
    for (i = 0; i < 3; i++) {
        if (!isfinite(area_turns[i]) || area_turns[i] <= 0.0 ||
            !isfinite(resistance[i]) || resistance[i] <= 0.0 ||
            !isfinite(voltage_limit[i]) || voltage_limit[i] < 0.0) {
            voltage->x = 0.0; voltage->y = 0.0; voltage->z = 0.0;
            realized->x = 0.0; realized->y = 0.0; realized->z = 0.0;
            *mask = 0U;
            return ADCS_E_RANGE;
        }
    }

    /* Process each coil */
    for (i = 0; i < 3; i++) {
        double raw_voltage = resistance[i] * requested[i] / area_turns[i];

        /* Voltage bound and clipping */
        if (raw_voltage > voltage_limit[i]) {
            v[i] = voltage_limit[i];
            m |= (1u << i);
        } else if (raw_voltage < -voltage_limit[i]) {
            v[i] = -voltage_limit[i];
            m |= (1u << i);
        } else {
            v[i] = raw_voltage;
        }

        /* Realized dipole calculation */
        r_dipole[i] = v[i] * area_turns[i] / resistance[i];
    }

    /* Fill outputs */
    voltage->x = v[0]; voltage->y = v[1]; voltage->z = v[2];
    realized->x = r_dipole[0]; realized->y = r_dipole[1]; realized->z = r_dipole[2];
    *mask = m;

    return ADCS_OK;
}

