candidates.raw:
    adcs_status_t status = ADCS_OK;
    unint32 sat_mask = 0U;
    double raw_v;
    double limited_v;
    size_t i;

    /* Validate pointers */
    if ((requested == NULL) || (area_turns == NULL) || (resistance == NULL) || 
        (voltage_limit == NULL) || (voltage == NULL) || (realized == NULL) || (mask == NULL)) {
        return ADCS_E_NULL;
    }

    /* Validate calibration parameters and input finiteness */
    for (i = 0; i < 3; i++) {
        if (!isfinite(area_turns[i]) || area_turns[i] <= 0.0 ||
            !isfinite(resistance[i]) || resistance[i] <= 0.0 ||
            !isfinite(voltage_limit[i]) || voltage_limit[i] < 0.0) {
            *voltage = (adcs_vec3_t){0.0, 0.0, 0.0};
            *realized = (adcs_vec3_t){0.0, 0.0, 0.0};
            *mask = 0U;
            return ADCS_E_RANGE;
        }
    }

    if (!adcs_is_finite_vec3(requested)) {
        *voltage = (adcs_vec3_t){0.0, 0.0, 0.0};
        *realized = (adcs_vec3_t){0.0, 0.0, 0.0};
        *mask = 0U;
        return ADCS_E_RANGE;
    }

    /* Process each coil axis individually */
    for (i = 0; i < 3; i++) {
        /* Map index to field name: 0->x, 1->y, 2->z */
        double req_val = 0.0;
        if (i == 0) req_val = requested->x;
        else if (i == 1) req_val = requested->y;
        else req_val = requested->z;

        /* Raw voltage calculation: V_raw = R * m_req / A_N */
        raw_v = resistance[i] * req_val / area_turns[i];

        /* Voltage bounding and clipping detection */
        if (fabs(raw_v) > voltage_limit[i]) {
            sat_mask |= (1u << i);
            limited_v = copysign(voltage_limit[i], raw_v);
        } else {
            limited_v = raw_v;
        }

        /* Output voltage */
        if (i == 0) voltage->x = limited_v;
        else if (i == 1) voltage->y = limited_v;
        else voltage->z = limited_v;

        /* Realized dipole calculation: m_real = V_limited * A_N / R */
        double real_val = limited_v * area_turns[i] / resistance[i];
        if (i == 0) realized->x = real_val;
        else if (i == 1) realized->y = real_val;
        else realized->z = real_val;
    }

    *mask = sat_mask;
    return ADCS_OK;
}

